cat > /tmp/repro.py <<'EOF'
import copy, tempfile, sys
sys.path.insert(0, '.')
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import ec
from vcbackend.store import TRUST_ANCHOR_USES, VCStore

def gen_pub():
    priv = ec.generate_private_key(ec.SECP256R1())
    return priv.public_key().public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo).decode()

CURSOR_ATTRS = [
    "_history_cursor", "_key_revocation_cursors", "_key_lifecycle_cursors",
    "_trust_anchor_history_cursors", "_trust_anchor_uses_history_cursors",
    "_local_credential_status_history_cursors", "_did_history_cursors",
    "_did_deactivation_event_cursors", "_trust_anchor_change_cursors",
]

def full_state(s):
    return {
        "tenants": copy.deepcopy(s._tenants),
        "audit": copy.deepcopy(s._audit),
        "audit_seq": s._audit_seq,
        **{a: copy.deepcopy(getattr(s, a)) for a in CURSOR_ATTRS},
    }

def typeshape(x):
    if isinstance(x, dict):
        return {type(k).__name__: typeshape(v) for k, v in list(x.items())[:1]}
    if isinstance(x, list):
        return [typeshape(x[0])] if x else []
    return type(x).__name__

path = tempfile.mktemp(suffix=".json")
s = VCStore(path)
p1, p2, p3 = gen_pub(), gen_pub(), gen_pub()
T, D = "t1", "did:web:x"

steps = [
    ("register", lambda: s.register_trust_anchor(T, D, p1, 1)),
    ("register idem", lambda: s.register_trust_anchor(T, D, p1, 1)),
    ("register tenant2", lambda: s.register_trust_anchor("t2", "did:web:y", p3, 2)),
    ("rotate", lambda: s.rotate_trust_anchor(T, D, 1, p2)),
    ("update_uses", lambda: s.update_trust_anchor_uses(T, D, 1, list(TRUST_ANCHOR_USES), ["vc","vp"])),
    ("revoke", lambda: s.revoke_trust_anchor(T, D, 1)),
    ("revoke idem", lambda: s.revoke_trust_anchor(T, D, 1)),
]
for name, fn in steps:
    fn()
    s2 = VCStore(path)
    a, b = full_state(s), full_state(s2)
    if a != b:
        print(f"MISMATCH after {name}:")
        for k in a:
            if a[k] != b[k]:
                print("  attr:", k)
                print("   mem:", a[k] if k != "tenants" else "<tenants>")
                print("   new:", b[k] if k != "tenants" else "<tenants>")
    else:
        print(f"OK {name}")
    # compare types too
    for k in a:
        if typeshape(a[k]) != typeshape(b[k]):
            print(f"  TYPE DIFF {k}: mem {typeshape(a[k])} vs new {typeshape(b[k])}")
    # reload twice more: must be identical
    s3 = VCStore(path)
    if full_state(s3) != b:
        print(f"  RE-RELOAD DRIFT after {name}")
EOF
