import tempfile, sys
sys.path.insert(0, '.')
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import ec
from vcbackend.store import TRUST_ANCHOR_USES, VCStore

def gen_pub():
    priv = ec.generate_private_key(ec.SECP256R1())
    return priv.public_key().public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo).decode()

def typeskeleton(x):
    if isinstance(x, dict):
        keytypes = sorted({type(k).__name__ for k in x})
        return ("dict", keytypes, sorted((k, typeskeleton(v)) for k, v in x.items()))
    if isinstance(x, list):
        return ["list", sorted({type(i).__name__ for i in x}),
                [typeskeleton(i) for i in x]]
    return type(x).__name__

path = tempfile.mktemp(suffix=".json")
s = VCStore(path)
p1, p2 = gen_pub(), gen_pub()
T, D = "t1", "did:web:x"
for name, fn in [
    ("register", lambda: s.register_trust_anchor(T, D, p1, 1)),
    ("rotate", lambda: s.rotate_trust_anchor(T, D, 1, p2)),
    ("update_uses", lambda: s.update_trust_anchor_uses(T, D, 1, list(TRUST_ANCHOR_USES), ["vc","vp"])),
    ("revoke", lambda: s.revoke_trust_anchor(T, D, 1)),
]:
    fn()
    s2 = VCStore(path)
    for attr in ["_tenants","_audit"]:
        a, b = getattr(s, attr), getattr(s2, attr)
        if typeskeleton(a) != typeskeleton(b):
            print(f"TYPE DIFF {name} {attr}")
            ta, tb = typeskeleton(a), typeskeleton(b)
            def walk(p, q, path=""):
                if type(p) != type(q):
                    print("  ", path, p, "vs", q); return
                if isinstance(p, tuple) and p[0]=="dict":
                    for (k1,v1),(k2,v2) in zip(p[2], q[2]):
                        walk(v1, v2, f"{path}.{k1}")
                elif isinstance(p, list) and p and p[0]=="list":
                    for i,(u,v) in enumerate(zip(p[2], q[2])):
                        walk(u, v, f"{path}[]")
            walk(ta, tb)
print("type skeleton check done")
